"use client";

/**
 * Letter wave: a title arrives letter by letter in a travelling wave with a
 * small bounce. The lead words come first, scaling up toward the viewer, and a
 * soft ripple runs along the title once it has landed.
 *
 * Written by Better Design. Painted from the theme prop, so the title takes the
 * product's ink and the lead words take its primary colour.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import { AbsoluteFill, interpolate, spring, useCurrentFrame, useVideoConfig } from "remotion";
import { pickFont, progress, springs, type VideoTheme, useVideoTheme } from "@/lib/bd-video";

const { fontFamily: INTER } = loadFont("normal", { weights: ["800"], subsets: ["latin"] });

export interface LetterWaveProps {
  /** The title. Short titles read best. */
  text?: string;
  /** How many words at the start lead the wave and take the primary colour. */
  lead?: number;
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
}

const LEAD_GAP = 2.2;
const REST_AT = 16;
const REST_GAP = 1.6;
const RIPPLE_AT = 62;
const RIPPLE_GAP = 1.4;

/** A title that rides in on a wave, its lead words first. */
export function LetterWave({
  text = "Made to be watched",
  lead = 1,
  theme: themeOverride,
  font,
}: LetterWaveProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const family = pickFont(font, theme, INTER);
  const words = text.split(/\s+/).filter(Boolean);
  const leadCount = Math.max(0, Math.min(words.length, lead));
  const size = Math.min(168, Math.round(2600 / Math.max(8, text.length)));

  let restIndex = 0;
  let leadIndex = 0;

  return (
    <AbsoluteFill style={{ background: theme.background, alignItems: "center", justifyContent: "center", fontFamily: family, padding: 160 }}>
      <h1
        style={{
          margin: 0,
          fontSize: size,
          fontWeight: 800,
          lineHeight: 1.08,
          letterSpacing: "-0.045em",
          color: theme.foreground,
          textAlign: "center",
          maxWidth: 1600,
        }}
      >
        {words.map((word, wi) => {
          const isLead = wi < leadCount;
          return (
            <span key={wi} style={{ display: "inline-block", whiteSpace: "nowrap", marginRight: wi < words.length - 1 ? "0.24em" : 0 }}>
              {Array.from(word).map((ch, ci) => {
                const start = isLead ? leadIndex++ * LEAD_GAP : REST_AT + restIndex++ * REST_GAP;
                const s = spring({ frame: frame - start, fps, config: springs.bouncy });
                const rise = interpolate(s, [0, 1], [0.9, 0]);
                const scale = isLead ? interpolate(s, [0, 1], [0.35, 1]) : interpolate(s, [0, 1], [0.86, 1]);
                // Once everything has landed, one gentle bump runs along the title.
                const order = isLead ? leadIndex : leadCount > 0 ? restIndex + 4 : restIndex;
                const bump = Math.sin(Math.PI * progress(frame, RIPPLE_AT + order * RIPPLE_GAP, 12)) * 0.08;
                return (
                  <span
                    key={ci}
                    style={{
                      display: "inline-block",
                      color: isLead ? theme.primary : theme.foreground,
                      opacity: interpolate(s, [0, 0.4], [0, 1], { extrapolateRight: "clamp" }),
                      transform: `translateY(${rise - bump}em) scale(${scale})`,
                      transformOrigin: "50% 100%",
                      filter: isLead ? `blur(${Math.max(0, 1 - s) * 10}px)` : undefined,
                    }}
                  >
                    {ch}
                  </span>
                );
              })}
            </span>
          );
        })}
      </h1>
    </AbsoluteFill>
  );
}
